{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    data = case.get("payload", case)
    if not isinstance(data, dict):
        raise ValueError("payload must be an object")
    if "nodes" not in data or "required_symbols" not in data:
        raise ValueError("missing required fields")

    nodes = data["nodes"]
    required_symbols = data["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if any(not isinstance(symbol, str) or not symbol for symbol in required_symbols):
        raise ValueError("required symbols must be non-empty strings")

    by_id = {}
    required_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    for node in nodes:
        if not isinstance(node, dict) or not required_fields.issubset(node):
            raise ValueError("each node must contain every required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node IDs must be non-empty strings")
        if node_id in by_id:
            raise ValueError("node IDs must be unique")
        if parent is not None and (not isinstance(parent, str) or not parent):
            raise ValueError("parent must be null or a non-empty node ID")
        if not isinstance(symbol, str) or not symbol:
            raise ValueError("symbols must be non-empty strings")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        if not math.isfinite(utility):
            raise ValueError("utility must be finite")

        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("the parse tree must have exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        raise ValueError("the root must have depth zero")

    children = {node_id: set() for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("every parent must reference an existing node")
        if parent == node["id"]:
            raise ValueError("a node cannot be its own parent")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("node depths must agree with parent links")
        children[parent].add(node["id"])

    visited = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in visited:
            raise ValueError("the parse tree must be acyclic")
        visited.add(node_id)
        stack.extend(children[node_id])
    if len(visited) != len(nodes):
        raise ValueError("all nodes must belong to the rooted parse tree")

    required = set(required_symbols)
    represented = {node["symbol"] for node in nodes}
    if not required.issubset(represented):
        raise ValueError("every required symbol must be represented initially")

    retained = set(by_id)
    removal_order = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        tentative = retained - {node_id}
        remaining_symbols = {by_id[item]["symbol"] for item in tentative}
        if not required.issubset(remaining_symbols):
            continue

        retained = tentative
        removal_order.append(node_id)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order,
        "grammar_valid": True,
        "interestingness_preserved": True,
        "registered_candidate_order": True,
        "stable_ties": True
    }
